package findu.backend.report.dto; import findu.backend.report.entity.Report; public record ReportResponse(Long id, Long reporterId, String targetType, Long targetId, String reason, String description, String status, java.time.LocalDateTime createdAt){public static ReportResponse from(Report x){return new ReportResponse(x.getId(),x.getReporter().getId(),x.getTargetType(),x.getTargetId(),x.getReason(),x.getDescription(),x.getStatus().name(),x.getCreatedAt());}}
